import{_ as e,o as r,c as a,a5 as d}from"./chunks/framework.BF53ZjCA.js";const p=JSON.parse('{"title":"斜方晶系","description":"","frontmatter":{"title":"斜方晶系","crystalSystem":"orthorhombic"},"headers":[],"relativePath":"zh/classification/crystal-systems/orthorhombic.md","filePath":"zh/classification/crystal-systems/orthorhombic.md","lastUpdated":1790876393000}'),l={name:"zh/classification/crystal-systems/orthorhombic.md"};function o(i,t,s,n,h,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="斜方晶系" tabindex="-1">斜方晶系 <a class="header-anchor" href="#斜方晶系" aria-label="Permalink to &quot;斜方晶系&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>斜方晶系三条晶轴两两正交但长度互不相等。晶体为二轴晶，具两条 光轴；正负光性因品种而异。本晶系涵盖金绿宝石族、橄榄石族等 多个宝石族系。</p><h2 id="晶体学参数" tabindex="-1">晶体学参数 <a class="header-anchor" href="#晶体学参数" aria-label="Permalink to &quot;晶体学参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>值</th></tr></thead><tbody><tr><td>晶轴</td><td>a ≠ b ≠ c</td></tr><tr><td>夹角</td><td>α = β = γ = 90°</td></tr><tr><td>对称性等级</td><td>medium</td></tr><tr><td>光学分类</td><td>biaxial</td></tr><tr><td>光性</td><td>+ or −</td></tr><tr><td>双折射率范围</td><td>0.040–0.180</td></tr><tr><td>解理</td><td>good parallel to one or two pinacoids</td></tr><tr><td>常见晶形</td><td>斜方柱、斜方双锥、板状</td></tr></tbody></table><h2 id="主要宝石" tabindex="-1">主要宝石 <a class="header-anchor" href="#主要宝石" aria-label="Permalink to &quot;主要宝石&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>折射率</th><th>比重</th></tr></thead><tbody><tr><td>Topaz</td><td>1.609–1.643</td><td>3.49–3.57</td></tr><tr><td>Tanzanite (Zoisite)</td><td>1.685–1.735</td><td>3.15–3.38</td></tr><tr><td>Alexandrite / Chrysoberyl</td><td>1.745–1.755</td><td>3.71–3.75</td></tr><tr><td>Peridot (Olivine)</td><td>1.635–1.690</td><td>3.28–3.48</td></tr><tr><td>Iolite (Cordierite)</td><td>1.522–1.578</td><td>2.57–2.66</td></tr><tr><td>Danburite</td><td>1.630–1.636</td><td>2.97–3.03</td></tr><tr><td><em>详见<a href="./../intro.html">分类总览</a>。</em></td><td></td><td></td></tr></tbody></table><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">参考依据与证据边界</h2><p class="gem-reference-block__intro">本页内容用于学习与检索；来源用于说明知识依据，不代表仅凭本页即可完成具体样品鉴定。</p><ul><li><a href="https://www.open.edu/openlearn/science-maths-technology/an-introduction-minerals-and-rocks-under-the-microscope/content-section-1.6.3/?tip=linktip" target="_blank" rel="noreferrer">Open University：晶体系统</a><span>晶系、晶轴关系与对称性基础</span><small>打开来源 ↗</small></li><li><a href="https://australian.museum/learn/minerals/what-are-minerals/crystallography/" target="_blank" rel="noreferrer">Australian Museum：晶体学</a><span>晶体结构与矿物学分类背景</span><small>打开来源 ↗</small></li><li><a href="https://www.gia.edu/gems-gemology/summer-2025-phenomenal-gemstones" target="_blank" rel="noreferrer">GIA：现象宝石的结构</a><span>宝石学中的结构与光学观察线索</span><small>打开来源 ↗</small></li></ul></aside>',8)])])}const b=e(l,[["render",o]]);export{p as __pageData,b as default};
